import type { EvidenceRef, FollowUpRule } from "@/lib/followup/rules";
import type { RiskKind } from "@/lib/risk/kinds";

/**
 * The outline for a phone call, when another email is not the move.
 *
 * Email is the default because it is what Selryn can draft, send and then
 * observe a reply to — the whole loop stays inside the product. But a thread
 * that has gone one-way for three weeks does not need a fourth message into
 * it, and a seller staring at that deal wants to know what to say when
 * somebody picks up.
 *
 * Deliberately **not** generated by a model, and deliberately not a script.
 *
 * Not generated, because there is nothing to generate from: the useful content
 * of a call outline is the handful of facts already on the deal — what we
 * sent, when, what they asked that nobody answered — and a model adding prose
 * around those facts can only dilute them or invent around them. The draft
 * emails run through a model because an email has to be written; an outline
 * has to be *true*.
 *
 * Not a script, because a script read aloud is obvious, and because the one
 * thing this can do well is make sure the seller is not the person on the call
 * who has forgotten what was already discussed.
 *
 * Pure. Every line traces to a record the caller can see for themselves.
 */

export interface CallOutline {
  /** The single purpose of the call, in one line. */
  objective: string;
  /** What the caller should already know, each line from a record. */
  context: string[];
  /** The one question worth asking. */
  ask: string;
  /** What to agree before hanging up. */
  close: string;
  /** Records the context lines came from, so each can be checked. */
  evidence: EvidenceRef[];
}

function dateLabel(d: Date): string {
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

function daysBetween(from: Date, to: Date): number {
  return Math.max(0, Math.floor((to.getTime() - from.getTime()) / 86_400_000));
}

export interface CallOutlineInput {
  accountName: string;
  contactName: string | null;
  risk: RiskKind;
  rule: FollowUpRule | null;
  /** Why Selryn raised this, already written in the seller's language. */
  because: string;
  /** The open question, when the blocker layer found one on record. */
  openQuestion: string | null;
  lastOutbound: EvidenceRef | null;
  lastInbound: EvidenceRef | null;
  lastActivity: EvidenceRef | null;
  nextStepDueAt: Date | null;
}

/**
 * Builds the outline.
 *
 * The objective varies by risk because the purpose of the call does: chasing
 * a silent proposal and answering a question they asked are different calls,
 * and giving both the same opening is how a generic tool sounds generic.
 */
export function buildCallOutline(input: CallOutlineInput, now: Date): CallOutline {
  const who = input.contactName?.split(/\s+/)[0] ?? "whoever picks up";
  const context: string[] = [];
  const evidence: EvidenceRef[] = [];

  if (input.lastOutbound) {
    const days = daysBetween(input.lastOutbound.occurredAt, now);
    context.push(
      `You last wrote on ${dateLabel(input.lastOutbound.occurredAt)} (${days} days ago)` +
        (input.lastOutbound.summary ? ` — “${input.lastOutbound.summary}”.` : ".")
    );
    evidence.push(input.lastOutbound);
  }

  if (input.lastInbound) {
    context.push(
      `They last came back on ${dateLabel(input.lastInbound.occurredAt)}` +
        (input.lastInbound.summary ? ` — “${input.lastInbound.summary}”.` : ".")
    );
    evidence.push(input.lastInbound);
  } else {
    // Stated plainly rather than omitted: the caller should know they are
    // opening a conversation, not continuing one.
    context.push("Nothing has come back from them on record, so treat this as a cold opener.");
  }

  if (input.openQuestion) {
    context.push(`Unanswered on record: ${input.openQuestion}`);
  }

  if (input.nextStepDueAt && input.nextStepDueAt <= now) {
    context.push(
      `The follow-up date on the deal was ${dateLabel(input.nextStepDueAt)} and passed.`
    );
  }

  const objective =
    input.risk === "open_question"
      ? `Answer the question ${who} asked, on the phone, and find out what is still open.`
      : input.risk === "followup_overdue"
        ? `Close the loop you opened with ${who} — you said you would come back and have not.`
        : input.risk === "meeting_no_next_step"
          ? `Agree a concrete next step with ${who}; the last meeting ended without one.`
          : input.risk === "awaiting_response"
            ? `Find out where ${input.accountName} actually stands on what you sent.`
            : `Find out whether ${input.accountName} is still looking at this at all.`;

  const ask =
    input.risk === "open_question"
      ? "Ask whether your answer covers it, and what else they need before deciding."
      : input.risk === "meeting_no_next_step"
        ? "Ask what would be a useful next step, and offer two concrete times."
        : "Ask one open question and stop talking: “Where has this ended up on your side?”";

  const close =
    input.risk === "meeting_no_next_step" || input.risk === "followup_overdue"
      ? "Leave with a date in the diary, and put it on the deal before you forget."
      : "Leave with either a date or a clear no. Both are better than another silent week.";

  return { objective, context, ask, close, evidence };
}
